package com.cyberyichen.bloub;
import android.content.Context;
import android.graphics.*;
import android.os.*;
import android.util.Log;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import com.google.mediapipe.framework.image.*;
import com.google.mediapipe.tasks.core.BaseOptions;
import com.google.mediapipe.tasks.components.containers.*;
import com.google.mediapipe.tasks.vision.core.RunningMode;
import com.google.mediapipe.tasks.vision.facelandmarker.*;
import com.google.mediapipe.tasks.vision.handlandmarker.*;
import com.google.mediapipe.tasks.vision.holisticlandmarker.*;
/** Optional local overlays, with one newest-frame job and no link to pet or occupancy decisions. */
final class LandmarkHub {
  private final Context context;private final HandlerThread thread=new HandlerThread("BloubLandmarks");private final Handler worker;private final AtomicBoolean busy=new AtomicBoolean();
  private volatile boolean faceWanted,handWanted,holisticWanted,closed;private volatile int generation;private long lastOffer;private volatile long retryAt;private FaceLandmarker face;private HandLandmarker hand;private HolisticLandmarker holistic;
  private volatile Frame latest;private volatile String status="关闭";private volatile double inferenceMs;
  static final class Frame {final long at;final List<List<NormalizedLandmark>> faces,hands;final List<NormalizedLandmark> pose;Frame(long at,List<List<NormalizedLandmark>> faces,List<List<NormalizedLandmark>> hands,List<NormalizedLandmark> pose){this.at=at;this.faces=faces;this.hands=hands;this.pose=pose;}}
  LandmarkHub(Context context){this.context=context.getApplicationContext();thread.start();worker=new Handler(thread.getLooper());}
  void layers(boolean f,boolean h,boolean whole){if(faceWanted==f&&handWanted==h&&holisticWanted==whole)return;faceWanted=f;handWanted=h;holisticWanted=whole;generation++;retryAt=0;latest=null;status=f||h||whole?"准备检测":"关闭";worker.post(()->{if((!faceWanted||holisticWanted)&&face!=null){face.close();face=null;}if((!handWanted||holisticWanted)&&hand!=null){hand.close();hand=null;}if(!holisticWanted&&holistic!=null){holistic.close();holistic=null;}});}
  boolean wanted(){return !closed&&(faceWanted||handWanted||holisticWanted);}
  boolean readyForFrame(long now){return wanted()&&!busy.get()&&now>=retryAt&&now-lastOffer>=300;}
  void offer(Bitmap image,long at){if(!wanted()||!busy.compareAndSet(false,true)){image.recycle();return;}lastOffer=at;final int version=generation;final boolean f=faceWanted,h=handWanted,whole=holisticWanted;worker.post(()->{MPImage input=null;try{if(closed||version!=generation)return;long began=SystemClock.elapsedRealtime();input=new BitmapImageBuilder(image).build();List<List<NormalizedLandmark>> faces=Collections.emptyList(),hands=Collections.emptyList();List<NormalizedLandmark> pose=Collections.emptyList();
    if(whole){if(holistic==null)holistic=HolisticLandmarker.createFromOptions(context,HolisticLandmarker.HolisticLandmarkerOptions.builder().setBaseOptions(BaseOptions.builder().setModelAssetPath("holistic-landmarker.task").build()).setRunningMode(RunningMode.VIDEO).build());HolisticLandmarkerResult r=holistic.detectForVideo(input,at);faces=r.faceLandmarks().isEmpty()?Collections.emptyList():Collections.singletonList(r.faceLandmarks());ArrayList<List<NormalizedLandmark>> hs=new ArrayList<>();if(!r.leftHandLandmarks().isEmpty())hs.add(r.leftHandLandmarks());if(!r.rightHandLandmarks().isEmpty())hs.add(r.rightHandLandmarks());hands=Collections.unmodifiableList(hs);pose=r.poseLandmarks();}
    else{if(f){if(face==null)face=FaceLandmarker.createFromOptions(context,FaceLandmarker.FaceLandmarkerOptions.builder().setBaseOptions(BaseOptions.builder().setModelAssetPath("face-landmarker.task").build()).setNumFaces(2).setRunningMode(RunningMode.VIDEO).build());faces=face.detectForVideo(input,at).faceLandmarks();}if(h){if(hand==null)hand=HandLandmarker.createFromOptions(context,HandLandmarker.HandLandmarkerOptions.builder().setBaseOptions(BaseOptions.builder().setModelAssetPath("hand-landmarker.task").build()).setNumHands(2).setRunningMode(RunningMode.VIDEO).build());hands=hand.detectForVideo(input,at).landmarks();}}
    if(!closed&&version==generation){latest=new Frame(at,faces,hands,pose);inferenceMs=SystemClock.elapsedRealtime()-began;status="检测中";}
  }catch(Throwable e){if(version==generation){latest=null;retryAt=SystemClock.elapsedRealtime()+10000;status="检测暂不可用";}Log.w("BloubLandmarks","Inference",e);}finally{if(input!=null)input.close();image.recycle();busy.set(false);}});}
  String info(){try{Frame f=latest;return new org.json.JSONObject().put("status",status).put("faceEnabled",faceWanted).put("handEnabled",handWanted).put("holisticEnabled",holisticWanted).put("faces",f==null?0:f.faces.size()).put("hands",f==null?0:f.hands.size()).put("posePoints",f==null?0:f.pose.size()).put("facePoints",f==null||f.faces.isEmpty()?0:f.faces.get(0).size()).put("handPoints",f==null||f.hands.isEmpty()?0:f.hands.get(0).size()).put("capturedAt",f==null?0:f.at).put("inferenceMs",inferenceMs).toString();}catch(Exception e){return "{}";}}
  void draw(Bitmap image,long at,boolean f,boolean h,boolean whole){draw(image,at,f,h,whole,true);}
  void draw(Bitmap image,long at,boolean f,boolean h,boolean whole,boolean labels){Frame data=latest;if(data==null||at<data.at||at-data.at>2500)return;Canvas canvas=new Canvas(image);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setStrokeWidth(Math.max(1,image.getWidth()/640f));if(f||whole){p.setColor(Color.rgb(61,211,167));for(List<NormalizedLandmark> points:data.faces){connections(canvas,p,points,FaceLandmarker.FACE_LANDMARKS_CONNECTORS,image);points(canvas,p,points,image,.9f);box(canvas,p,points,image,"面部",labels);}}if(h||whole){p.setColor(Color.rgb(250,199,91));for(List<NormalizedLandmark> points:data.hands){connections(canvas,p,points,HandLandmarker.HAND_CONNECTIONS,image);points(canvas,p,points,image,2);box(canvas,p,points,image,"手部",labels);}}if(whole&&!data.pose.isEmpty()){p.setColor(Color.rgb(101,179,255));int[][] lines={{11,12},{11,13},{13,15},{12,14},{14,16},{11,23},{12,24},{23,24},{23,25},{25,27},{24,26},{26,28},{27,29},{29,31},{28,30},{30,32}};for(int[] line:lines)line(canvas,p,data.pose,line[0],line[1],image);points(canvas,p,data.pose,image,2);}}
  void drawLabels(Bitmap image,long at,boolean f,boolean h,boolean whole,int turn,boolean mirror){drawLabels(image,at,f,h,whole,turn,mirror,null);}
  void drawLabels(Bitmap image,long at,boolean f,boolean h,boolean whole,int turn,boolean mirror,float[] crop){Frame data=latest;if(data==null||at<data.at||at-data.at>2500)return;if(f||whole)for(List<NormalizedLandmark> points:data.faces)label(image,points,"面部",Color.rgb(61,211,167),turn,mirror,crop);if(h||whole)for(List<NormalizedLandmark> points:data.hands)label(image,points,"手部",Color.rgb(250,199,91),turn,mirror,crop);}
  private static void label(Bitmap image,List<NormalizedLandmark> points,String text,int color,int turn,boolean mirror,float[] crop){float l=1,t=1,r=0,b=0;for(NormalizedLandmark p:points)if(visible(p)){l=Math.min(l,p.x());t=Math.min(t,p.y());r=Math.max(r,p.x());b=Math.max(b,p.y());}if(r>l&&b>t){float[] bounds=ImageTransform.bounds(l,t,r,b,turn,mirror,crop);if(bounds!=null)OverlayText.label(image,bounds,text,color);}}
  private static boolean visible(NormalizedLandmark l){return Float.isFinite(l.x())&&Float.isFinite(l.y())&&l.x()>=0&&l.x()<=1&&l.y()>=0&&l.y()<=1&&(!l.visibility().isPresent()||l.visibility().get()>=.4f);}
  private static void line(Canvas c,Paint p,List<NormalizedLandmark> points,int a,int b,Bitmap image){if(a>=points.size()||b>=points.size())return;NormalizedLandmark x=points.get(a),y=points.get(b);if(visible(x)&&visible(y))c.drawLine(x.x()*image.getWidth(),x.y()*image.getHeight(),y.x()*image.getWidth(),y.y()*image.getHeight(),p);}
  private static void connections(Canvas c,Paint p,List<NormalizedLandmark> points,Set<Connection> lines,Bitmap image){for(Connection line:lines)line(c,p,points,line.start(),line.end(),image);}
  private static void points(Canvas c,Paint p,List<NormalizedLandmark> points,Bitmap image,float radius){p.setStyle(Paint.Style.FILL);for(NormalizedLandmark l:points)if(visible(l))c.drawCircle(l.x()*image.getWidth(),l.y()*image.getHeight(),radius*image.getWidth()/640f,p);}
  private static void box(Canvas c,Paint p,List<NormalizedLandmark> points,Bitmap image,String label,boolean labels){float l=1,t=1,r=0,b=0;for(NormalizedLandmark x:points)if(visible(x)){l=Math.min(l,x.x());t=Math.min(t,x.y());r=Math.max(r,x.x());b=Math.max(b,x.y());}if(r<=l||b<=t)return;p.setStyle(Paint.Style.STROKE);c.drawRect(l*image.getWidth(),t*image.getHeight(),r*image.getWidth(),b*image.getHeight(),p);p.setStyle(Paint.Style.FILL);p.setTextSize(17*image.getWidth()/640f);if(labels)c.drawText(label,l*image.getWidth(),Math.max(20,t*image.getHeight()-6),p);}
  void close(){closed=true;generation++;latest=null;worker.post(()->{if(face!=null)face.close();if(hand!=null)hand.close();if(holistic!=null)holistic.close();thread.quitSafely();});}
}
